insert into fitmatch_taxonomy.decision_length_axes(decision_id,sleeve_length_class,pants_length_class,leggings_length_class,skirt_length_class,body_length_class,construction_type,policy_version)
select d.id,v.sleeve,v.pants,v.leggings,v.skirt,v.body,v.construction,'taxonomy-final-2026-08-03'
from v join fitmatch_taxonomy.source_categories c on c.source_snapshot_id=v.snapshot_id and c.source_code=v.source_code and c.external_category_id=v.external_id and c.target=v.target join fitmatch_taxonomy.classification_decisions d on d.source_category_id=c.id and d.policy_version='taxonomy-final-2026-08-03' on conflict(decision_id) do nothing;
commit;
